using System;

class GFG
{
    public static double log2(int x)
    {
        return (Math.Log(x) / Math.Log(2));
    }

    // Function to find the minimum number of rats 
    static int minRats(int n) 
    { 
        return (int)(Math.Ceiling(log2(n))); 
    } 

    // Driver Code 
